import React, { useState } from "react";
import "./style.css";
import { Helmet, HelmetProvider } from "react-helmet-async";
import { Container, Row, Col } from "react-bootstrap";
import { Link } from "react-router-dom";
import { meta } from "../../content_option";
import { useLanguage } from "../../i18n/LanguageContext";
import { blogPosts } from "../../data/blogData";

export const Blog = () => {
  const { t, language } = useLanguage();
  const [activeCategory, setActiveCategory] = useState('all');

  const posts = blogPosts[language] || blogPosts.en;

  const categories = [
    { id: 'all', label: t('blog.categories.all') },
    { id: 'ai', label: t('blog.categories.ai') },
    { id: 'ml', label: t('blog.categories.ml') },
    { id: 'trends', label: t('blog.categories.trends') },
    { id: 'tutorials', label: t('blog.categories.tutorials') },
    { id: 'case_studies', label: t('blog.categories.case_studies') },
  ];

  const filteredPosts = activeCategory === 'all'
    ? posts
    : posts.filter(post => post.category === activeCategory);

  const featuredPost = posts.find(post => post.featured);

  const pageTitle = language === 'pt'
    ? "Blog de IA | Artigos sobre Machine Learning & Inteligência Artificial - Tyber.io"
    : "AI Blog | Machine Learning & Artificial Intelligence Articles - Tyber.io";

  const pageDescription = language === 'pt'
    ? "Leia artigos sobre inteligência artificial, machine learning, NLP e tendências de IA. Insights e tutoriais da equipe de consultores da Tyber.io."
    : "Read articles about artificial intelligence, machine learning, NLP, and AI trends. Insights and tutorials from the Tyber.io consulting team.";

  return (
    <HelmetProvider>
      <section className="blog-page" itemScope itemType="https://schema.org/Blog">
        <Helmet>
          <html lang={language === 'pt' ? 'pt-BR' : 'en'} />
          <title>{pageTitle}</title>
          <meta name="description" content={pageDescription} />
          <link rel="canonical" href="https://tyber.io/blog" />
          <meta property="og:title" content={pageTitle} />
          <meta property="og:description" content={pageDescription} />
          <meta property="og:url" content="https://tyber.io/blog" />
          <meta property="og:type" content="website" />
          <meta name="twitter:title" content={pageTitle} />
          <meta name="twitter:description" content={pageDescription} />
        </Helmet>

        {/* Hero Section */}
        <div className="blog-hero">
          <Container>
            <div className="blog-hero__badge">
              <span className="badge-dot"></span>
              <span className="badge-text">{t('blog.badge')}</span>
            </div>
            <h1 className="blog-hero__title gradient-text">
              {t('blog.title')}
            </h1>
            <p className="blog-hero__subtitle">
              {t('blog.subtitle')}
            </p>

            <div className="page-stats-row">
              <div className="page-stat-card">
                <span className="page-stat-card__value">{t('blog.stats.articles.value')}</span>
                <span className="page-stat-card__label">{t('blog.stats.articles.label')}</span>
              </div>
              <div className="page-stat-card">
                <span className="page-stat-card__value">{t('blog.stats.topics.value')}</span>
                <span className="page-stat-card__label">{t('blog.stats.topics.label')}</span>
              </div>
              <div className="page-stat-card">
                <span className="page-stat-card__value">{t('blog.stats.readTime.value')}</span>
                <span className="page-stat-card__label">{t('blog.stats.readTime.label')}</span>
              </div>
            </div>
          </Container>
        </div>

        {/* Featured Post */}
        {featuredPost && (
          <Container className="blog-featured">
            <div className="featured-badge">{t('blog.featured')}</div>
            <div className="featured-post">
              <Row className="align-items-center">
                <Col lg={6}>
                  <div className="featured-post__image">
                    <img src={featuredPost.image} alt={featuredPost.title} />
                  </div>
                </Col>
                <Col lg={6}>
                  <div className="featured-post__content">
                    <div className="post-meta">
                      <span className="post-category">{featuredPost.category.toUpperCase()}</span>
                      <span className="post-separator">•</span>
                      <span className="post-date">{featuredPost.date}</span>
                      <span className="post-separator">•</span>
                      <span className="post-read">{featuredPost.readTime} {t('blog.readTime')}</span>
                    </div>
                    <h2 className="featured-post__title">{featuredPost.title}</h2>
                    <p className="featured-post__excerpt">{featuredPost.excerpt}</p>
                    <div className="post-author">
                      <div className="author-info">
                        <div className="author-name">{featuredPost.author}</div>
                        <div className="author-role">{featuredPost.authorRole}</div>
                      </div>
                    </div>
                    <Link to={`/blog/${featuredPost.slug}`} className="read-more-btn">
                      {t('blog.readMore')} →
                    </Link>
                  </div>
                </Col>
              </Row>
            </div>
          </Container>
        )}

        {/* Category Filters */}
        <Container className="blog-filters">
          <div className="filter-buttons">
            {categories.map(category => (
              <button
                key={category.id}
                className={`filter-btn ${activeCategory === category.id ? 'active' : ''}`}
                onClick={() => setActiveCategory(category.id)}
              >
                {category.label}
              </button>
            ))}
          </div>
        </Container>

        {/* Blog Posts Grid */}
        <Container className="blog-section">
          <Row>
            {filteredPosts.map((post) => (
              <Col lg={4} md={6} key={post.id} className="mb-4">
                <article className="blog-card">
                  <div className="blog-card__image">
                    <img src={post.image} alt={post.title} />
                    <div className="blog-card__category">{post.category.toUpperCase()}</div>
                  </div>
                  <div className="blog-card__content">
                    <div className="blog-card__meta">
                      <span className="date">{post.date}</span>
                      <span className="separator">•</span>
                      <span className="read-time">{post.readTime} {t('blog.readTime')}</span>
                    </div>
                    <h3 className="blog-card__title">{post.title}</h3>
                    <p className="blog-card__excerpt">{post.excerpt}</p>
                    <div className="blog-card__author">
                      <div className="author-details">
                        <div className="author-name">{post.author}</div>
                        <div className="author-role">{post.authorRole}</div>
                      </div>
                    </div>
                    <Link to={`/blog/${post.slug}`} className="blog-card__link">
                      {t('blog.readMore')} →
                    </Link>
                  </div>
                </article>
              </Col>
            ))}
          </Row>
        </Container>
      </section>
    </HelmetProvider>
  );
};
